with flattened_attrs as (select id, effective_from, currency, tier_limits, tier_prices, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, slice(tier_limits, 1, 2) as first_two_limits, array_min(tier_prices) as lowest_price, element_at(tier_prices, 1) as entry_price from price_tiers where currency in ('EUR', 'THB', 'USD')) select *, row_number() over (partition by currency order by effective_from, id) as event_seq, sum(entry_price) over (partition by currency order by effective_from, id rows between unbounded preceding and current row) as running_entry_price from flattened_attrs
